<?php
declare(strict_types=1);require getcwd().'/public/index.php';$n=0;
function yes(bool $v,string $s):void{if(!$v)throw new RuntimeException($s);echo 'PASS '.$s.PHP_EOL;$GLOBALS['n']++;}
function deny(callable $f,string $s):void{try{$f();}catch(InvalidArgumentException|PDOException){yes(true,$s);return;}throw new RuntimeException('Not rejected: '.$s);}
$db=db();$db->exec('DELETE FROM bonus_hours');$b=$db->query('SELECT * FROM businesses WHERE id=1')->fetch();$other=$db->query('SELECT * FROM businesses WHERE id=2')->fetch();
function writeop($b,$args,$target,$id){return merchant_write($b,['operation'=>bin2hex(random_bytes(16))]+$args,$target,$id);}
$x=['operation'=>str_repeat('a',32),'name'=>'WordPress Test','email'=>'wp@test.local'];$r=merchant_write($b,$x,'member',0);$mid=$r['member']['id'];yes($mid>0,'member created');yes(merchant_write($b,$x,'member',0)===$r,'create replay returns same result');yes((int)$db->query("SELECT COUNT(*) FROM members WHERE email='wp@test.local'")->fetchColumn()===1,'no duplicate member');
deny(fn()=>merchant_write($b,array_merge($x,['name'=>'Changed']),'member',0),'conflicting operation rejected');deny(fn()=>writeop($b,['name'=>'Duplicate','email'=>'WP@test.local'],'member',0),'case-insensitive email uniqueness');
yes(writeop($b,['name'=>'New name','email'=>'wp@test.local'],'member',$mid)['ok'],'member name editable');deny(fn()=>writeop($b,['name'=>'X','email'=>'changed@test.local'],'member',$mid),'email identity immutable');deny(fn()=>writeop($other,['name'=>'X','email'=>'wp@test.local'],'member',$mid),'other-tenant member update blocked');
$c=$db->query("SELECT c.* FROM cards c JOIN programs p ON p.id=c.program_id WHERE c.member_id=$mid AND p.type='points'")->fetch();$cid=(int)$c['id'];$op=['operation'=>str_repeat('b',32),'action'=>'points_add','amount'=>25];$result=merchant_write($b,$op,'card',$cid);yes($result['points']===25,'points added');yes(merchant_write($b,$op,'card',$cid)===$result,'points replay stable');yes((int)$db->query("SELECT COUNT(*) FROM transactions WHERE card_id=$cid")->fetchColumn()===1,'points journal exactly once');deny(fn()=>merchant_write($b,array_merge($op,['amount'=>26]),'card',$cid),'points conflict blocked');deny(fn()=>writeop($other,['action'=>'points_add','amount'=>1],'card',$cid),'cross-tenant card blocked');
foreach([0,-1,10001,'oops','1.5'] as $amount)deny(fn()=>writeop($b,['action'=>'points_add','amount'=>$amount],'card',$cid),'invalid points rejected '.(string)$amount);
$pid=(int)$c['program_id'];$db->exec("INSERT INTO rewards(program_id,name,points_cost)VALUES($pid,'WP reward',10)");$rid=(int)$db->lastInsertId();$red=['operation'=>str_repeat('c',32),'action'=>'redeem_reward','reward_id'=>$rid];yes(merchant_write($b,$red,'card',$cid)['points']===15,'reward deducts exact cost');merchant_write($b,$red,'card',$cid);yes((int)$db->query("SELECT points FROM cards WHERE id=$cid")->fetchColumn()===15,'reward replay no second deduction');writeop($b,['action'=>'redeem_reward','reward_id'=>$rid],'card',$cid);deny(fn()=>writeop($b,['action'=>'redeem_reward','reward_id'=>$rid],'card',$cid),'insufficient points blocked');
$sc=$db->query("SELECT c.*,p.stamps_required FROM cards c JOIN programs p ON p.id=c.program_id WHERE c.member_id=$mid AND p.type='stamps'")->fetch();$sid=(int)$sc['id'];$db->exec('UPDATE cards SET stamps='.((int)$sc['stamps_required']-1)." WHERE id=$sid");$stamp=['operation'=>str_repeat('d',32),'action'=>'stamp'];$result=merchant_write($b,$stamp,'card',$sid);yes($result['stamps']===0 && $result['pending_rewards']===1,'stamp rollover earns reward');merchant_write($b,$stamp,'card',$sid);yes(writeop($b,['action'=>'redeem_stamp_reward'],'card',$sid)['pending_rewards']===0,'stamp reward redeemed once');deny(fn()=>writeop($b,['action'=>'redeem_stamp_reward'],'card',$sid),'no extra reward redemption');deny(fn()=>writeop($b,['action'=>'points_add','amount'=>1],'card',$sid),'wrong card type blocked');
$db->exec("UPDATE programs SET active=0 WHERE id=$pid");deny(fn()=>writeop($b,['action'=>'points_add','amount'=>1],'card',$cid),'inactive program blocked');$db->exec("UPDATE programs SET active=1 WHERE id=$pid");
$db->exec("DELETE FROM members WHERE id=$mid");deny(fn()=>merchant_write($b,$x,'member',0),'erased customer cannot be recreated by replay');yes($db->query("SELECT request_hash FROM merchant_operations WHERE operation='".$x['operation']."'")->fetchColumn()==='erased','erased operation tombstone holds no request fields');
echo $n.' merchant domain assertions passed'.PHP_EOL;
